#!/usr/bin/env python3
import sys, os, json, csv, gzip, io
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    t = data.decode('utf-8-sig')
    return t


def lines_of(path):
    t = read_text(path)
    return [l for l in t.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def csv_rows(path, **kw):
    return list(csv.reader(lines_of(path), **kw))


def local_to_ts(zone, naive, fold):
    d = naive.replace(tzinfo=zone, fold=fold)
    return int(d.timestamp()) if False else int((d.astimezone(UTC) - datetime(1970, 1, 1, tzinfo=UTC)).total_seconds())


def std_offset(zone):
    for m in (1, 7, 4, 10):
        d = datetime(2026, m, 1, tzinfo=zone)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
    return int(datetime(2026, 1, 1, tzinfo=zone).utcoffset().total_seconds())


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def to_ts(dt):
    return int((dt - datetime(1970, 1, 1, tzinfo=UTC)).total_seconds() // 1)


def fold_from_abbr(ab, dst_words, std_words):
    ab = ab.strip().upper()
    for w in dst_words:
        if ab.endswith(w):
            return 0
    return 1


def read_abbr(path, zone):
    out = []
    hdr = None
    for row in csv_rows(path):
        cells = [c.strip() for c in row]
        if 'Badge' in cells and 'Punch' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        mo, dd, yy = g('Date').split('/')
        tm = g('Time').upper()
        ampm = None
        if tm.endswith('AM') or tm.endswith('PM'):
            ampm = tm[-2:]
            tm = tm[:-2].strip()
        h, mi, s = [int(x) for x in tm.split(':')]
        if ampm:
            h = h % 12 + (12 if ampm == 'PM' else 0)
        naive = datetime(int(yy), int(mo), int(dd), h, mi, s)
        fold = 0 if g('Zone').strip().upper().endswith('DT') else 1
        d = g('Punch').strip().upper()
        out.append((g('Record').strip(), g('Badge'), 'IN' if d == 'IN' else 'OUT', local_to_ts(zone, naive, fold)))
    return out


def read_epoch(path, zone):
    out = []
    schema = 1
    for l in lines_of(path):
        o = json.loads(l)
        if 'schema' in o and 'punch_id' not in o and 'id' not in o:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid = o['punch_id']; emp = o['employee']; d = o['direction']
            ts = int(o['epoch_ms']) // 1000
        else:
            pid = o['id']; emp = o['emp']; d = o['dir']
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'])
        out.append((str(pid), emp, 'IN' if str(d).upper() == 'IN' else 'OUT', ts))
    return out


def read_offset(path, zone):
    out = []
    rows = csv_rows(path, delimiter=';')
    hdr = None
    for row in rows:
        cells = [c.strip() for c in row]
        if 'punch_id' in cells and 'timestamp' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        ev = g('event').lower()
        out.append((g('punch_id'), g('employee'), 'IN' if ev == 'clock_in' else 'OUT', to_ts(parse_iso(g('timestamp')))))
    return out


def read_legacy(path, zone):
    out = []
    default = std_offset(zone)
    off = default
    for l in lines_of(path):
        t = l[0]
        if t == 'H':
            rest = l[13:18].strip()
            if rest and rest[0] in '+-' and len(rest) == 5:
                sec = (int(rest[1:3]) * 3600 + int(rest[3:5]) * 60)
                off = sec if rest[0] == '+' else -sec
            else:
                off = default
        elif t == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            d = l[15]
            dt = l[16:30]
            naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]), int(dt[12:14]))
            ts = to_ts(naive.replace(tzinfo=UTC)) - off
            out.append((pid, 'E' + badge, 'IN' if d == 'I' else 'OUT', ts))
    return out


def read_de(path, zone):
    out = []
    hdr = None
    for l in lines_of(path):
        cells = [c.strip() for c in l.split('\t')]
        if 'Ausweis' in cells and 'Buchung' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        dd, mo, yy = g('Datum').split('.')
        h, mi = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(yy), int(mo), int(dd), int(h), int(mi))
        fold = 0 if g('Zeitzone').upper() == 'MESZ' else 1
        out.append((g('Nr'), g('Ausweis'), 'IN' if g('Buchung').upper() == 'K' else 'OUT', local_to_ts(zone, naive, fold)))
    return out


def parse_local(s):
    s = s.strip().replace('T', ' ')
    return datetime.strptime(s, '%Y-%m-%d %H:%M:%S')


def read_localcsv(path, zone):
    out = []
    hdr = None
    for row in csv_rows(path):
        cells = [c.strip() for c in row]
        if 'employee_id' in cells and 'local_time' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        out.append((g('punch_ref'), g('employee_id'), 'IN' if g('direction').upper() == 'IN' else 'OUT',
                    local_to_ts(zone, parse_local(g('local_time')), 0)))
    return out


def read_localjsonl(path, zone):
    out = []
    for l in lines_of(path):
        o = json.loads(l)
        p = o.get('punch')
        if not isinstance(p, dict):
            continue
        out.append((str(p['id']), p['badge'], 'IN' if str(p['type']).upper() == 'IN' else 'OUT',
                    local_to_ts(zone, parse_local(p['at']), 0)))
    return out


READERS = {'abbr-csv': read_abbr, 'epoch-jsonl': read_epoch, 'offset-csv': read_offset,
           'legacy-fixed': read_legacy, 'de-tsv': read_de, 'local-csv': read_localcsv,
           'local-jsonl': read_localjsonl}


def offset_at(zone, ts):
    return int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())


def round_ts(zone, ts):
    off = offset_at(zone, ts)
    loc = ts + off
    r = ((loc + 180) // 360) * 360
    return r - off


def night_minutes(zone, a, b):
    if b <= a:
        return 0
    oa, ob = offset_at(zone, a), offset_at(zone, b)
    total = 0
    if oa == ob:
        la, lb = a + oa, b + oa
        day = (la // 86400) * 86400 - 86400
        while day <= lb:
            for s, e in ((day, day + 6 * 3600), (day + 22 * 3600, day + 30 * 3600)):
                lo, hi = max(s, la), min(e, lb)
                if hi > lo:
                    total += hi - lo
            day += 86400
        return total // 60
    t = a
    cnt = 0
    while t < b:
        step = min(60, b - t)
        h = ((t + offset_at(zone, t)) % 86400) // 3600
        if h >= 22 or h < 6:
            cnt += step
        t += step
    return cnt // 60


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = to_ts(parse_iso(period['corrections_cutoff']))

    sites = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'sites.csv')))):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'employees.csv')))):
        employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'rates.csv')))):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site,id) -> dict
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        files = []
        for root, _, fs in os.walk(d):
            for f in fs:
                files.append(os.path.join(root, f))
        for path in sorted(files):
            for pid, emp, direc, ts in READERS[fmt](path, zone):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = {'emp': emp.strip(), 'dir': direc, 'ts': ts}

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, fs in os.walk(cdir):
            for f in fs:
                for r in csv.DictReader(io.StringIO(read_text(os.path.join(root, f)))):
                    r = {k: (v or '').strip() for k, v in r.items() if k}
                    corr.append(r)
    corr = [(to_ts(parse_iso(r['issued_at'])), r) for r in corr]
    corr = [c for c in corr if c[0] <= cutoff]
    corr.sort(key=lambda c: (c[0], c[1]['correction_id']))
    applied = 0
    voided = set()
    for _, r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action'].lower()
        if a == 'void':
            if k in punches and k not in voided:
                voided.add(k)
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches and k not in voided:
                punches[k]['ts'] = to_ts(parse_iso(r['time']))
                applied += 1
        elif a == 'add':
            if k not in ever and r['site'] in sites:
                ever.add(k)
                punches[k] = {'emp': r['employee'], 'dir': 'IN' if r['type'].upper() == 'IN' else 'OUT',
                              'ts': to_ts(parse_iso(r['time']))}
                applied += 1

    per = {}
    for (site, pid), p in punches.items():
        if p['emp'] in employees:
            per.setdefault(p['emp'], []).append((p['ts'], 0 if p['dir'] == 'OUT' else 1, site, pid, p['dir']))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def rnd_item(site, ts):
        return round_ts(sites[site][0], ts)

    for emp, lst in per.items():
        hz = sites[employees[emp]][0] if employees[emp] in sites else UTC
        def workday(ts):
            return datetime.fromtimestamp(ts, UTC).astimezone(hz).date()
        def inper(ts):
            return pstart <= workday(ts) <= pend
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, d in lst:
            rt = rnd_item(site, ts)
            if last is not None and last[4] == d and ts - last[0] <= 300:
                if inper(rt):
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, 0, site, pid, d, rt)
            kept.append(last)
        shifts = []
        pend_in = None
        for ts, _, site, pid, d, rt in kept:
            if d == 'IN':
                if pend_in is not None and inper(pend_in[5]):
                    exc['open_shifts'] += 1
                pend_in = (ts, 0, site, pid, d, rt)
            else:
                if pend_in is not None and rt - pend_in[5] <= 16 * 3600:
                    shifts.append((pend_in, rt))
                    pend_in = None
                else:
                    if pend_in is not None:
                        if inper(pend_in[5]):
                            exc['open_shifts'] += 1
                        pend_in = None
                    if inper(rt):
                        exc['orphan_outs'] += 1
        if pend_in is not None and inper(pend_in[5]):
            exc['open_shifts'] += 1
        rows = []
        for i, rt_out in shifts:
            rin = i[5]
            wd = workday(rin)
            if not (pstart <= wd <= pend):
                continue
            zone = sites[i[2]][0]
            worked = max(0, (rt_out - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(zone, rin, rt_out), paid)
            rows.append([rin, wd, paid, night, 0, 0])
        rows.sort(key=lambda r: r[0])
        dayacc = {}
        for r in rows:
            used = dayacc.get(r[1], 0)
            dot = max(0, used + r[2] - 480) - max(0, used - 480)
            dayacc[r[1]] = used + r[2]
            r[4] = dot
        weekacc = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            used = weekacc.get(wk, 0)
            nd = r[2] - r[4]
            wot = max(0, used + nd - 2400) - max(0, used - 2400)
            weekacc[wk] = used + nd
            r[5] = wot
        s = res[emp]
        rl = rates.get(emp, [])
        for rin, wd, paid, night, dot, wot in rows:
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, rv in rl:
                if ef <= wd:
                    rate = rv
            s['shifts'] += 1
            s['paid_minutes'] += paid
            s['overtime_minutes'] += ot
            s['night_minutes'] += night
            s['gross'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    def money(fr):
        c = (fr * 100)
        q = (c.numerator * 2 + c.denominator) // (2 * c.denominator)
        return q
    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    for e in sorted(res):
        s = res[e]
        c = money(s['gross'])
        out_emps[e] = dict(shifts=s['shifts'], paid_minutes=s['paid_minutes'], overtime_minutes=s['overtime_minutes'],
                           night_minutes=s['night_minutes'], gross='%d.%02d' % (c // 100, c % 100))
        for k in tot:
            tot[k] += s[k]
        totc += c
    tot['gross'] = '%d.%02d' % (totc // 100, totc % 100)
    json.dump({'period': {'start': period['start'], 'end': period['end']}, 'employees': out_emps,
               'exceptions': exc, 'totals': tot}, open(outp, 'w'), indent=1)


main()
